#define GARLIC_PROFILE_COUNT (sizeof(garlic_fw_profiles) / sizeof(garlic_fw_profiles[0]))

/* An exact version is required, no nearest-version fallback. */
static inline const garlic_fw_offsets_profile *garlic_fw_find(uint32_t raw_fw) {
  const uint32_t fw = raw_fw & 0xffff0000u;
  for (size_t i = 0; i < GARLIC_PROFILE_COUNT; ++i) {
    if (garlic_fw_profiles[i].version == fw) return &garlic_fw_profiles[i];
  }
  return NULL;
}

/* Verify the addresses populated by the matching SDK CRT BEFORE save work. */
static inline int garlic_fw_validate(uint32_t raw_fw, uintptr_t base,
                                    uintptr_t text, uintptr_t allproc,
                                    uintptr_t security, uintptr_t rootvnode,
                                    uintptr_t bus) {
  const garlic_fw_offsets_profile *p = garlic_fw_find(raw_fw);
  if (!p || !base || base < p->text_minus ||
      UINTPTR_MAX-base < p->allproc_plus ||
      UINTPTR_MAX-base < p->security_plus ||
      UINTPTR_MAX-base < p->rootvnode_plus ||
      UINTPTR_MAX-base < p->bus_plus) return 0;
  return text == base - p->text_minus &&
         allproc == base + p->allproc_plus &&
         security == base + p->security_plus &&
         rootvnode == base + p->rootvnode_plus &&
         bus == base + p->bus_plus;
}

#ifndef GARLIC_FW_GUARD_HOST_TEST
static inline int garlic_fw_offsets_preflight(void) {
  const uint32_t fw = kernel_get_fw_version();
  if (!garlic_fw_validate(fw, (uintptr_t)KERNEL_ADDRESS_DATA_BASE,
                              (uintptr_t)KERNEL_ADDRESS_TEXT_BASE,
                              (uintptr_t)KERNEL_ADDRESS_ALLPROC,
                              (uintptr_t)KERNEL_ADDRESS_SECURITY_FLAGS,
                              (uintptr_t)KERNEL_ADDRESS_ROOTVNODE,
                              (uintptr_t)KERNEL_ADDRESS_BUS_DATA_DEVICES)) {
    fprintf(stderr, "[GarlicMgr] SDK CRT offsets mismatch/unsupported FW: 0x%08x; aborting.\n", fw);
    return 0;
  }
  printf("[GarlicMgr] firmware profile check passed: 0x%08x (SDK CRT).\n", fw);
  return 1;
}
#endif
